class NotificationsScreen extends ConsumerStatefulWidget{const NotificationsScreen({super.key});@override ConsumerState<NotificationsScreen> createState()=>_NotificationsScreenState();}
class _NotificationsScreenState extends ConsumerState<NotificationsScreen>{int tab=0;Map<String,List<Map<String,dynamic>>> groups={'pending':[],'today':[],'upcoming':[]};List<Map<String,dynamic>> history=[],payments=[];bool enabled=false,permission=false,loading=true;
@override void initState(){super.initState();load();}
Future<void> load()async{setState(()=>loading=true);try{await ReminderService.refreshFromCloud();final results=await Future.wait([ReminderService.currentCategories(),ReminderService.history(),ReminderService.candidates(),ReminderService.remindersEnabled(),ReminderService.paymentPermission()]);if(!mounted)return;setState((){groups=results[0] as Map<String,List<Map<String,dynamic>>>;history=results[1] as List<Map<String,dynamic>>;payments=results[2] as List<Map<String,dynamic>>;enabled=results[3] as bool;permission=results[4] as bool;loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext context){final overdue=(groups['pending']??[]).where((x)=>'${x['date']??''}'<dateKey(DateTime.now().toUtc())).toList();final tabs=['Overdue','Due today','Upcoming','Payments','History'];return Scaffold(appBar:AppBar(title:const Text('Notifications'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,4,16,25),children:[Card(color:AppColors.teal,child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Overdue to collect',style:TextStyle(color:Colors.white70)),const SizedBox(height:4),Text(moneyLabel(overdue.fold<double>(0,(v,x)=>v+((x['balance'] as num?)?.toDouble()??0))),style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w900,fontSize:22))])),Column(crossAxisAlignment:CrossAxisAlignment.end,children:[Text('Due today ${groups['today']?.length??0}',style:const TextStyle(color:Colors.white)),Text('Upcoming ${groups['upcoming']?.length??0}',style:const TextStyle(color:Colors.white70))])]))),Card(child:SwitchListTile(title:const Text('Daily reminders',style:TextStyle(fontWeight:FontWeight.w700)),subtitle:const Text('Local notification once a day using the latest synced bills'),value:enabled,onChanged:(v)async{await ReminderService.setReminders(v);await load();})),Card(child:ListTile(title:const Text('Payment detection',style:TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(permission?'Enabled · received payment notices are suggestions only':'Optional Android notification access'),leading:const Icon(Icons.account_balance_outlined),trailing:OutlinedButton(onPressed:()async{await NotificationListenerService.requestPermission();await load();},child:Text(permission?'Manage':'Enable')))),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:List.generate(tabs.length,(i)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text('${tabs[i]}${i==0?' (${overdue.length})':''}'),selected:tab==i,onSelected:(_)=>setState(()=>tab=i)))))),const SizedBox(height:12),if(tab<3)..._reminderCards(context,tab==0?overdue:tab==1?groups['today']??[]:groups['upcoming']??[]),if(tab==3)..._paymentCards(context),if(tab==4)..._historyCards()]))));}
List<Widget> _reminderCards(BuildContext context,List<Map<String,dynamic>> rows)=>rows.isEmpty?[EmptyState(title:tab==0?'No overdue bills':tab==1?'Nothing due today':'No upcoming bills',description:tab==2?'No rental cycle begins in the next seven days.':'Bills with payment pending will appear here.',icon:Icons.notifications_none)]:rows.map((r)=>Card(margin:const EdgeInsets.only(bottom:9),child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('${r['name']??'Customer'}',style:const TextStyle(fontWeight:FontWeight.w800,fontSize:16))),Text(moneyLabel(r['balance']??0),style:const TextStyle(fontWeight:FontWeight.w900,color:AppColors.red))]),Text('${r['isCustom']==true?'Custom':'Bill'} #${r['billNo']} · ${r['date']??''}'),if(tab==0)Text('${_daysLate('${r['date']??''}')} days late',style:const TextStyle(color:AppColors.red,fontSize:12)),const SizedBox(height:10),Wrap(spacing:7,children:[if('${r['mobile']??''}'.isNotEmpty)OutlinedButton.icon(onPressed:()=>_call(r),icon:const Icon(Icons.call_outlined),label:const Text('Call')),if('${r['mobile']??''}'.isNotEmpty)OutlinedButton.icon(onPressed:()=>_whatsapp(context,r),icon:const Icon(Icons.chat_outlined),label:const Text('WhatsApp')),FilledButton.tonalIcon(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Open this bill from the Bills tab.'))),icon:const Icon(Icons.receipt_long_outlined),label:const Text('View bill'))])])))).toList();
int _daysLate(String date){final d=parseBillingDate(date);if(d==null)return 0;final now=DateTime.now().toUtc();return (DateTime.utc(now.year,now.month,now.day).difference(d).inDays).clamp(0,99999);}
void _call(Map<String,dynamic> r){final phone='${r['mobile']}'.replaceAll(RegExp(r'[^0-9+]'), '');launchUrl(Uri.parse('tel:$phone'));}
Future<void> _whatsapp(BuildContext context,Map<String,dynamic> row)async{final rawPhone='${row['mobile']}'.replaceAll(RegExp(r'\D'),'');final to=rawPhone.length==10?'91$rawPhone':rawPhone;final text='Hello ${row['name']??'Customer'},\n\n$businessName rental bill reminder.\n${row['isCustom']==true?'Custom bill':'Bill'} #${row['billNo']}\n${tab==2?'Upcoming cycle date':'Due date'}: ${row['date']}\n${tab==2?'Expected cycle amount':'Pending amount'}: ${moneyLabel(row['balance']??0)}\n\n${tab==2?'This is an advance reminder for your upcoming rental cycle.':'Please arrange payment. If you have already paid, please share the payment details so we can update your bill.'}\n\nThank you.\n$businessName\n$businessPhones';final ctrl=TextEditingController(text:text);final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Review WhatsApp reminder'),content:SizedBox(width:450,child:TextField(controller:ctrl,maxLines:10,decoration:InputDecoration(helperText:'To: +$to'))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Open WhatsApp'))]));if(ok==true){final uri=Uri.https('wa.me','/$to',{'text':ctrl.text});if(!await launchUrl(uri,mode:LaunchMode.externalApplication)&&context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('WhatsApp could not be opened.')));}ctrl.dispose();}
List<Widget> _paymentCards(BuildContext context)=>payments.isEmpty?[const EmptyState(title:'No detected payments',description:'Received payment notifications from supported UPI and bank apps will appear here.',icon:Icons.account_balance_wallet_outlined)]:payments.reversed.map((p)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(isThreeLine:true,leading:const CircleAvatar(child:Icon(Icons.currency_rupee)),title:Text('${moneyLabel(p['amount']??0)} · ${p['source']}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${p['text']}\n${p['reference']??''}'),trailing:IconButton(tooltip:'Assign or split',onPressed:()=>showDialog(context:context,builder:(_)=>_SplitReceiptDialog(item:p,onSaved:load)),icon:const Icon(Icons.call_split_outlined))))).toList();
List<Widget> _historyCards()=>history.isEmpty?[const EmptyState(title:'No notification history',description:'Delivered daily reminder notices are recorded on this phone.')]:history.reversed.map((x)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(leading:const Icon(Icons.history),title:Text('${x['name']??'Reminder'}'),subtitle:Text('${x['date']??''} · ${x['text']??''}')))).toList();
}

class _Allocation { _Allocation(this.store,this.bill,this.cycle);final String store;final Map<String,dynamic> bill;final Map<String,dynamic>? cycle;final amount=TextEditingController(); }
class _SplitReceiptDialog extends ConsumerStatefulWidget{const _SplitReceiptDialog({required this.item,required this.onSaved});final Map<String,dynamic> item;final VoidCallback onSaved;@override ConsumerState<_SplitReceiptDialog> createState()=>_SplitReceiptDialogState();}
class _SplitReceiptDialogState extends ConsumerState<_SplitReceiptDialog>{List<Map<String,dynamic>> bills=[];String? customer;bool credit=false,busy=false;List<_Allocation> allocations=[];String? error;
@override void initState(){super.initState();loadBills();}
Future<void> loadBills()async{final repo=ref.read(billingRepositoryProvider);final now=DateTime.now().toUtc();final today=DateTime.utc(now.year,now.month,now.day);final [rawRental,rawCustom]=await Future.wait([repo.all('bills'),repo.all('customBills')]);final rows=<Map<String,dynamic>>[];for(final r in rawRental){final b=hydrateRentalBill(r,today:today);if(b['status']=='closed'||(b['pending'] as num)<=0)continue;rows.add({...b,'_store':'bills'});}for(final r in rawCustom){if(r['converted_to_professional']==true)continue;final total=customBillTotal(r),paid=((r['payments'] as List? ?? const []).fold<double>(0,(v,x)=>v+(((x as Map)['amount'] as num?)?.toDouble()??0)));if(total<=paid)continue;rows.add({...r,'pending':(total-paid).clamp(0,double.infinity),'_store':'customBills','cycles':<Map>[]});}if(mounted)setState(()=>bills=rows);}
String _phone(Map b)=>'${b['mobile']??''}'.replaceAll(RegExp(r'\D'),'');
void chooseCustomer(String? key){setState((){customer=key;for(final x in allocations)x.amount.dispose();allocations=[];final selected=bills.where((b)=>_phone(b)==key).toList();for(final b in selected){if(b['_store']=='customBills'){allocations.add(_Allocation('customBills',b,null));}else{for(final c in (b['cycles'] as List).cast<Map>()){final amount=(c['total'] as num?)?.toDouble()??0;if(amount>0)allocations.add(_Allocation('bills',b,Map<String,dynamic>.from(c)));}}}});}
double _amount(_Allocation a)=>double.tryParse(a.amount.text)??0;
@override Widget build(BuildContext context){final customers={for(final b in bills)if(_phone(b).isNotEmpty)_phone(b):'${b['name']??'Customer'} · ${_phone(b)}'};return AlertDialog(title:const Text('Allocate detected payment'),content:SizedBox(width:500,child:!bills.isNotEmpty?const Center(child:CircularProgressIndicator()):SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Received ${moneyLabel(widget.item['amount']??0)} · ${widget.item['source']??''}'),const SizedBox(height:10),DropdownButtonFormField<String>(value:customer,decoration:const InputDecoration(labelText:'Customer'),items:customers.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value,overflow:TextOverflow.ellipsis))).toList(),onChanged:chooseCustomer),if(customer!=null)...[const SizedBox(height:12),...allocations.map((a)=>Padding(padding:const EdgeInsets.only(bottom:9),child(Row(children:[Expanded(child:Text(a.cycle==null?'Custom #${a.bill['bill_no']}':'Bill #${a.bill['bill_no']} · cycle #${a.cycle!['index']}\n${a.cycle!['start_date']}',style:const TextStyle(fontSize:12))),SizedBox(width:110,child:TextField(controller:a.amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(prefixText:'₹',hintText:'0.00'),onChanged:(_)=>setState((){})))]))),CheckboxListTile(value:credit,onChanged:(v)=>setState(()=>credit=v??false),title:const Text('Keep unallocated amount as customer credit'),contentPadding:EdgeInsets.zero),Builder(builder:(context){final received=(widget.item['amount'] as num).toDouble();final sum=allocations.fold<double>(0,(v,a)=>v+_amount(a));return Text('Allocated ${moneyLabel(sum)} · Remaining ${moneyLabel(received-sum)}',style:const TextStyle(fontWeight:FontWeight.w800));})],if(error!=null)Padding(padding:const EdgeInsets.only(top:10),child:Text(error!,style:const TextStyle(color:AppColors.red)))]))),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:busy?null:save,child:Text(busy?'Saving…':'Confirm & save'))]);}
Future<void> save()async{try{setState(()=>error=null);final received=((widget.item['amount'] as num).toDouble()*100).round();var allocated=0;final byBill=<String,int>{};final values=<_Allocation,int>{};for(final a in allocations){final cents=((_amount(a)*100).round());if(cents<0)throw Exception('Enter valid amounts.');final capacity=a.cycle==null?((a.bill['pending'] as num).toDouble()*100).round():((a.cycle!['total'] as num).toDouble()*100).round();if(cents>capacity)throw Exception('An allocation exceeds that cycle balance.');if(cents>0){final id='${a.store}:${a.bill['bill_no']}';byBill[id]=(byBill[id]??0)+cents;values[a]=cents;allocated+=cents;}}for(final entry in byBill.entries){final bill=allocations.firstWhere((a)=>'${a.store}:${a.bill['bill_no']}'==entry.key).bill;if(entry.value>((bill['pending'] as num).toDouble()*100).round())throw Exception('Bill allocation exceeds pending balance.');}if(allocated>received)throw Exception('Allocated amount exceeds the detected receipt.');final remainder=received-allocated;if(remainder>0&&(!credit||customer==null))throw Exception('Allocate the full receipt or choose customer credit.');if(values.isEmpty&&remainder==0)throw Exception('Enter at least one amount.');setState(()=>busy=true);final repo=ref.read(billingRepositoryProvider),refId='${widget.item['reference']??''}',itemId='${widget.item['id']}';final receiptKey=refId.isNotEmpty?'payment_receipt:ref:${refId.toUpperCase().replaceAll(RegExp(r'\s+'),'')}':'payment_receipt:id:$itemId';final all=[...await repo.all('bills'),...await repo.all('customBills')];for(final b in all){for(final p in (b['payments'] as List? ?? const [])){if(p['detected_payment_id']==itemId||(refId.isNotEmpty&&p['transaction_reference']==refId))throw Exception('This transaction is already recorded.');}}final ops=<({String store,Map<String,dynamic> data})>[];final groups=<String,List<_Allocation>>{};for(final a in values.keys){groups.putIfAbsent('${a.store}:${a.bill['bill_no']}',()=>[]).add(a);}final savedAllocations=<Map<String,dynamic>>[];for(final group in groups.entries){final sep=group.key.indexOf(':');final store=group.key.substring(0,sep),billNo=group.key.substring(sep+1);final raw=await repo.get(store,billNo);if(raw==null)throw Exception('A selected bill no longer exists.');final payments=(raw['payments'] as List? ?? []).map((p)=>Map<String,dynamic>.from(p as Map)).toList();for(final a in group.value){final paymentId='pay-${DateTime.now().microsecondsSinceEpoch}-${savedAllocations.length}';final amount=values[a]!/100;final c=a.cycle;payments.add({'payment_id':paymentId,'receipt_key':receiptKey,'amount':amount,'payment_date':DateTime.now().toIso8601String().substring(0,10),'method':'UPI','note':'Split receipt · ${widget.item['source']??'UPI'}','detected_payment_id':itemId,'transaction_reference':refId,'payment_source':widget.item['source']??'UPI',if(c!=null)'cycle_index':c['index'],if(c!=null)'cycle_start_date':c['start_date'],if(c!=null)'cycle_end_date':c['end_date'],'created_at':DateTime.now().toUtc().toIso8601String(),'created_by':ref.read(authRepositoryProvider).currentUser?.email??''});savedAllocations.add({'store':store,'bill_no':billNo,'cycle_index':c?['index'],'cycle_start_date':c?['start_date']??'','cycle_end_date':c?['end_date']??'','amount':amount,'payment_id':paymentId});}ops.add((store:store,data:{...raw,'payments':payments,'updated_at':DateTime.now().toUtc().toIso8601String()}));}final customerMobile=customer??'';if(customerMobile.isNotEmpty){final existing=await repo.get('customers',customerMobile);final receipts=(existing?['payment_credit_receipts'] as List? ?? []).where((x)=>(x as Map)['receipt_key']!=receiptKey).map((x)=>Map<String,dynamic>.from(x as Map)).toList();if(remainder>0)receipts.add({'receipt_key':receiptKey,'amount':remainder/100,'created_at':DateTime.now().toUtc().toIso8601String()});final balance=receipts.fold<double>(0,(v,x)=>v+((x['amount'] as num).toDouble()));ops.add((store:'customers',data:{'mobile':customerMobile,'customer_id':existing?['customer_id']??'','name':existing?['name']??'','place':existing?['place']??'','created_at':existing?['created_at']??DateTime.now().toUtc().toIso8601String(),'payment_credit_receipts':receipts,'payment_credit_balance':balance}));}final item=Map<String,dynamic>.from(widget.item);final receipt={'kind':'split_payment_receipt','receipt_key':receiptKey,'item':item,'payment_date':DateTime.now().toIso8601String().substring(0,10),'amount':received/100,'allocations':savedAllocations,'credit':remainder/100,'customerKey':'phone:$customerMobile','customer_mobile':customerMobile,'customer_name':bills.firstWhere((b)=>_phone(b)==customerMobile)['name']??'Customer','version':1,'status':'active','created_at':DateTime.now().toUtc().toIso8601String(),'updated_at':DateTime.now().toUtc().toIso8601String(),'audit':<Map>[]};ops.add((store:'settings',data:{'key':receiptKey,'value':receipt}));final alias='payment_receipt:id:$itemId';if(alias!=receiptKey)ops.add((store:'settings',data:{'key':alias,'value':{'kind':'split_receipt_alias','receipt_key':receiptKey}}));await repo.batch(ops);await ReminderService.dismiss(itemId);if(mounted){Navigator.pop(context);widget.onSaved();}}catch(e){if(mounted)setState(()=>error='$e');}finally{if(mounted)setState(()=>busy=false);}}
}
